for msIndex, sets in pairs(EXTRA_SETS) do
    local ms = ProjectEbonhold.PrestigeData.Milestones[msIndex]
    if ms and ms.item then
        local list = { ms.item }
        for _, s in ipairs(sets) do
            list[#list + 1] = { type = "transmogSet", name = s.name, items = s.items }
        end
        ms.items = list
        ms.item = nil
    end
end
